import numpy as np

def r(x):
    # The Lorenz system has a minimum final norm near x = 0.5, where the initial state
    # lies on the invariant z-axis and decays. Moving x away from 0.5 towards the 
    # boundaries (0.0 or 1.0) systematically increases the initial state's norm and 
    # its distance from the z-axis, resulting in a larger final state norm at t=1.0.
    if x >= 0.5:
        return min(x + 0.2, 1.0)
    else:
        return max(x - 0.2, 0.0)

def R(y_orig, y_new):
    return float(y_new) >= float(y_orig) - 1e-9
